const dashboardHtml: string = "<!DOCTYPE html>\r\n<html lang=\"id\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\r\n<title>Relay Gateway Dashboard</title>\r\n<link rel=\"icon\" id=\"dynamicFavicon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%233b5bfd' stroke-width='2.2'><path d='M4 12h12M12 6l6 6-6 6'/></svg>\">\r\n<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\r\n<style>\r\n:root{--bg:#eef1f6;--card:#fff;--ink:#141c2b;--mute:#6a7488;--line:#dfe4ec;--side:#151d36;--side-ink:#aab3cc;--acc:#3b5bfd;--acc-s:#e6ebff;--ok:#12805c;--ok-s:#dcf5ea;--bad:#c43a3a;--bad-s:#fde5e5;--warn:#9a6700;--warn-s:#fff1cc;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}\r\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#0d1220;--card:#161d30;--ink:#e8ecf6;--mute:#8d97b0;--line:#26304a;--side:#0a0f1c;--acc:#7f95ff;--acc-s:#222c55;--ok:#4ed1a1;--ok-s:#123a2e;--bad:#ff8585;--bad-s:#431c22;--warn:#f2c14e;--warn-s:#3b2f10}}\r\n:root[data-theme=\"dark\"]{--bg:#0d1220;--card:#161d30;--ink:#e8ecf6;--mute:#8d97b0;--line:#26304a;--side:#0a0f1c;--acc:#7f95ff;--acc-s:#222c55;--ok:#4ed1a1;--ok-s:#123a2e;--bad:#ff8585;--bad-s:#431c22;--warn:#f2c14e;--warn-s:#3b2f10}\r\n*{box-sizing:border-box}html{scroll-padding-top:env(safe-area-inset-top,0px)}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 \"Plus Jakarta Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif;min-height:100vh}\r\nbody.modal-open{overflow:hidden!important;touch-action:none}\r\nbutton,input,select{font:inherit;color:inherit}\r\nbutton{cursor:pointer}\r\n:focus-visible{outline:2px solid var(--acc);outline-offset:2px}\r\n.hide{display:none!important}\r\n\r\n/* Login Card */\r\n#login{min-height:100vh;display:grid;place-items:center;padding:20px}\r\n.lcard{width:100%;max-width:380px;background:var(--card);border:1px solid var(--line);border-radius:18px;padding:32px}\r\n.logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:18px;letter-spacing:-.02em}\r\n.logo-img{width:30px;height:30px;border-radius:8px;object-fit:contain}\r\n.mark{width:32px;height:32px;border-radius:9px;background:var(--acc);display:grid;place-items:center;color:#fff;flex:none}\r\n.mark.has-logo{background:transparent!important}\r\n.mark svg{width:18px;height:18px}\r\n.lcard h1{font-size:22px;margin:24px 0 4px;letter-spacing:-.02em}\r\n.lcard p{margin:0 0 20px;color:var(--mute)}\r\nlabel{display:block;font-weight:600;font-size:13px;margin:14px 0 6px}\r\ninput[type=text],input[type=email],input[type=password],select{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--bg);box-sizing:border-box}\r\n.input-wrap{position:relative;display:flex;align-items:center}\r\n.input-wrap input{padding-right:40px}\r\n.input-wrap .btn-eye{position:absolute;right:8px;border:0;background:none;color:var(--mute);padding:6px;display:grid;place-items:center}\r\n\r\n/* Buttons & Icons */\r\n.btn{border:0;border-radius:10px;padding:9px 15px;font-weight:600;background:var(--acc);color:#fff;display:inline-flex;align-items:center;justify-content:center;gap:7px;transition:.15s;font-size:13px}\r\n.btn svg{width:16px;height:16px;flex:none}\r\n.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}\r\n.btn.ghost:hover{background:rgba(0,0,0,.04)}\r\n.btn.danger{background:var(--bad-s);color:var(--bad)}\r\n.btn.sm{padding:6px 10px;font-size:12px;border-radius:8px}\r\n.btn.sm svg{width:14px;height:14px}\r\n.btn.icon-only{padding:7px;border-radius:8px}\r\n.btn.square-btn{width:38px;height:38px;min-height:38px;max-height:38px;padding:0;display:inline-flex;align-items:center;justify-content:center;flex:none;border-radius:10px;aspect-ratio:1/1}\r\n.btn.square-btn svg{width:18px;height:18px}\r\n.btn.full{width:100%;margin-top:20px}\r\n.btn:active{transform:scale(.98)}\r\n.btn:disabled{opacity:.5;cursor:not-allowed;transform:none!important}\r\n\r\n@keyframes spin{to{transform:rotate(360deg)}}\r\n.spin{animation:spin .8s linear infinite}\r\n\r\n/* App Shell */\r\n#app{display:grid;grid-template-columns:240px 1fr;min-height:100vh}\r\naside{background:var(--side);color:var(--side-ink);padding:22px 14px;display:flex;flex-direction:column;gap:6px;position:sticky;top:0;height:100vh}\r\naside .logo{color:#fff;padding:0 8px 18px}\r\n.nav{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:10px;border:0;background:none;color:inherit;font-weight:600;text-align:left;width:100%}\r\n.nav svg{width:18px;height:18px;flex:none}\r\n.nav:hover{background:rgba(255,255,255,.06)}\r\n.nav.on{background:var(--acc);color:#fff}\r\n.spacer{flex:1}\r\nmain{padding:28px;max-width:1100px;width:100%;box-sizing:border-box}\r\n.top{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:22px}\r\nh2{margin:0;font-size:24px;letter-spacing:-.03em}\r\n.sub{color:var(--mute);margin:2px 0 0}\r\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;box-sizing:border-box}\r\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}\r\n.kpi{padding:16px}\r\n.kpi b{display:block;font-size:26px;letter-spacing:-.03em}\r\n.kpi span{color:var(--mute);font-size:13px}\r\n\r\n/* Client Table */\r\n.row{display:grid;grid-template-columns:2fr 2fr 1.2fr 1fr auto;gap:12px;align-items:center;padding:14px 18px;border-top:1px solid var(--line)}\r\n.row.head{border-top:0;color:var(--mute);font-weight:600;font-size:13px}\r\n.name{font-weight:700}\r\n.id{color:var(--mute);font-size:12px}\r\n.chips{display:flex;gap:6px;flex-wrap:wrap;align-items:center}\r\n.chip{padding:3px 9px;border-radius:99px;background:var(--acc-s);color:var(--acc);font-weight:600;font-size:12px;display:inline-flex;align-items:center;gap:4px}\r\n.chip.logic{background:var(--warn-s);color:var(--warn)}\r\n.badge{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:99px;font-weight:600;font-size:12px}\r\n.badge::before{content:\"\";width:7px;height:7px;border-radius:50%;background:currentColor}\r\n.badge.on{background:var(--ok-s);color:var(--ok)}.badge.off{background:var(--line);color:var(--mute)}\r\n.acts{display:flex;gap:6px;align-items:center}\r\n.empty{padding:40px 18px;text-align:center;color:var(--mute)}\r\n\r\n/* Target rows */\r\n.trow{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;border-top:1px solid var(--line);gap:10px}\r\n.addbar{display:flex;gap:8px;padding:16px 18px}\r\n.addbar input{flex:1}\r\n\r\n/* Toggle Switch (Swift) */\r\n.toggle{position:relative;width:44px;height:24px;flex:none}\r\n.toggle input{opacity:0;position:absolute;inset:0;margin:0;cursor:pointer;z-index:1}\r\n.toggle i{position:absolute;inset:0;background:var(--line);border-radius:99px;transition:.15s}\r\n.toggle i::after{content:\"\";position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:#fff;transition:.15s}\r\n.toggle input:checked+i{background:var(--acc)}.toggle input:checked+i::after{left:23px}\r\n.toggle input:focus-visible+i{outline:2px solid var(--acc);outline-offset:2px}\r\n\r\n/* Drawers - Z-INDEX 1000 ensures popup is NEVER covered by mobile header */\r\n.scrim{position:fixed;inset:0;background:rgba(10,14,28,.55);display:flex;justify-content:flex-end;z-index:1000;animation:fade .15s}\r\n.drawer{background:var(--card);width:100%;max-width:520px;height:100%;display:flex;flex-direction:column;box-shadow:-10px 0 36px rgba(0,0,0,.25);animation:slide .2s ease-out}\r\n.drawer-head{padding:18px 24px 16px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex:none}\r\n.drawer-head h2{margin:0;font-size:19px}\r\n.drawer-body{flex:1;overflow-y:auto;padding:20px 24px}\r\n.drawer-foot{padding:14px 24px calc(14px + env(safe-area-inset-bottom,0px));border-top:1px solid var(--line);background:var(--card);display:flex;gap:10px;justify-content:flex-end;flex:none;position:sticky;bottom:0;z-index:5}\r\n@keyframes slide{from{transform:translateX(30px);opacity:0}}@keyframes fade{from{opacity:0}}\r\n\r\n.seg{display:inline-flex;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:3px}\r\n.seg button{border:0;background:none;padding:6px 14px;border-radius:8px;font-weight:600;font-size:12.5px;color:var(--mute);display:inline-flex;align-items:center;gap:6px}\r\n.seg button svg{width:15px;height:15px}\r\n.seg button.on{background:var(--acc);color:#fff}\r\n.opt{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 14px;border:1px solid var(--line);border-radius:12px;margin-bottom:8px;font-weight:600}\r\n.sub-box{margin:-2px 0 10px;padding:12px;background:var(--bg);border-radius:10px}\r\n.tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}\r\n.tag{display:inline-flex;align-items:center;gap:6px;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:3px 4px 3px 9px;font-size:13px}\r\n.tag button{border:0;background:none;color:var(--mute);font-size:16px;line-height:1;padding:0 4px}\r\n.inline{display:flex;gap:8px;align-items:center}\r\n.secret-box{background:var(--warn-s);color:var(--warn);padding:8px 12px;border-radius:10px;display:flex;align-items:center;justify-content:space-between;gap:8px}\r\n.secret-box code{font-family:ui-monospace,Menlo,monospace;font-size:12.5px;word-break:break-all}\r\n.url-card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px;margin-top:10px}\r\n.url-card .title{font-size:12px;font-weight:700;color:var(--acc);margin-bottom:4px}\r\n.url-card .desc{font-size:11.5px;color:var(--mute);margin-bottom:8px}\r\n\r\n/* Settings Tabs Bar & Scroll Arrows */\r\n.tabs-nav-wrap{position:relative;display:flex;align-items:center;margin-bottom:20px;width:100%;max-width:100%;box-sizing:border-box}\r\n.tabs{display:flex;border-bottom:1px solid var(--line);gap:4px;overflow-x:auto;scrollbar-width:none;-ms-overflow-style:none;scroll-behavior:smooth;width:100%;box-sizing:border-box;padding:0 2px}\r\n.tabs::-webkit-scrollbar{display:none}\r\n.tab{border:0;background:none;padding:8px 14px;font-weight:600;font-size:13px;color:var(--mute);border-bottom:2px solid transparent;display:inline-flex;align-items:center;gap:6px;border-radius:8px 8px 0 0;white-space:nowrap;flex:none}\r\n.tab svg{width:15px;height:15px;flex:none}\r\n.tab:hover{color:var(--ink)}\r\n.tab.on{color:var(--acc);border-bottom-color:var(--acc);background:var(--bg)}\r\n.tabs-arrow{position:absolute;top:50%;transform:translateY(-50%);width:28px;height:28px;border-radius:50%;background:var(--card);border:1px solid var(--line);box-shadow:0 2px 8px rgba(0,0,0,.15);display:flex;align-items:center;justify-content:center;z-index:5;color:var(--ink);cursor:pointer;transition:opacity .15s;padding:0}\r\n.tabs-arrow svg{width:14px;height:14px}\r\n.tabs-arrow.left{left:0}\r\n.tabs-arrow.right{right:0}\r\n.tabs-arrow.hide{display:none!important}\r\n.tab-pane{display:none}\r\n.tab-pane.on{display:block}\r\n\r\n/* Analytics Graph & Logs Table */\r\n.chart-box{padding:20px;margin-top:16px;width:100%;max-width:100%;box-sizing:border-box;overflow:hidden}\r\n.chart-scroll-wrap{width:100%;max-width:100%;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;padding-bottom:8px;box-sizing:border-box}\r\n.chart-scroll-wrap::-webkit-scrollbar{height:4px}\r\n.chart-scroll-wrap::-webkit-scrollbar-track{background:transparent}\r\n.chart-scroll-wrap::-webkit-scrollbar-thumb{background:var(--line);border-radius:4px}\r\n.chart-bars{display:flex;align-items:flex-end;gap:6px;height:180px;padding-top:24px;min-width:580px;box-sizing:border-box}\r\n.bar-col{flex:1;min-width:16px;display:flex;flex-direction:column;align-items:center;height:100%;justify-content:flex-end;position:relative}\r\n.bar-fill{width:100%;max-width:24px;border-radius:4px 4px 0 0;background:var(--acc);min-height:0;transition:height .3s}\r\n.bar-fill.err{background:var(--bad)}\r\n.bar-time{font-size:10px;color:var(--mute);margin-top:6px;writing-mode:vertical-rl;transform:rotate(180deg)}\r\n.tooltip{position:absolute;top:-26px;background:var(--ink);color:var(--bg);padding:3px 6px;border-radius:4px;font-size:10px;white-space:nowrap;opacity:0;pointer-events:none;transition:.15s;z-index:20}\r\n.bar-col:hover .tooltip{opacity:1}\r\n\r\n.log-table-wrap{width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch}\r\n.log-table{width:100%;border-collapse:collapse;font-size:13px;min-width:620px}\r\n.log-table th{padding:12px 16px;text-align:left;color:var(--mute);font-weight:600;font-size:12px;border-bottom:1px solid var(--line);background:var(--bg)}\r\n.log-table td{padding:12px 16px;border-top:1px solid var(--line);vertical-align:middle}\r\n\r\n#toast{position:fixed;left:50%;bottom:calc(86px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:10px 16px;border-radius:10px;font-weight:600;z-index:2000;opacity:0;pointer-events:none;transition:.2s}\r\n#toast.show{opacity:1}\r\n.note{padding:14px 18px;color:var(--mute);border-top:1px solid var(--line)}\r\n.note a{color:var(--acc)}\r\n\r\n/* Mobile Responsive */\r\n.mbar{display:none}\r\n@media (max-width:860px){\r\n#app{grid-template-columns:1fr;overflow-x:hidden}\r\n.mbar{display:flex;align-items:center;justify-content:space-between;position:fixed;top:0;left:0;right:0;height:56px;min-height:56px;max-height:56px;box-sizing:border-box;z-index:50;background:var(--bg);padding:0 16px;padding-top:env(safe-area-inset-top,0px);border-bottom:1px solid var(--line);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}\r\naside{position:fixed;top:auto;bottom:0;left:0;right:0;height:auto;flex-direction:row;gap:0;padding:6px 8px calc(6px + env(safe-area-inset-bottom,0px));z-index:50}\r\naside .logo,.spacer,.nav.out{display:none}\r\n.nav{flex:1;flex-direction:column;justify-content:center;gap:3px;font-size:11px;padding:8px 4px;text-align:center;min-height:52px}\r\nmain{padding:calc(56px + 16px + env(safe-area-inset-top,0px)) 12px 140px;width:100%;max-width:100%;box-sizing:border-box;overflow-x:hidden}\r\n.kpis{grid-template-columns:repeat(2,1fr);gap:10px}\r\n.row.head{display:none}\r\n.row{grid-template-columns:1fr auto;grid-template-areas:\"n s\" \"c c\" \"t t\" \"a a\";gap:10px;background:var(--card);border:1px solid var(--line)!important;border-radius:14px;margin-bottom:10px}\r\n.row>:nth-child(1){grid-area:n}.row>:nth-child(2){grid-area:c}.row>:nth-child(3){grid-area:t;font-size:13px}.row>:nth-child(4){grid-area:s;justify-self:end}.row>:nth-child(5){grid-area:a;justify-self:end}\r\n.acts{display:flex;justify-content:flex-end;align-items:center;gap:8px;width:100%}\r\n.drawer{max-width:none;width:100%;height:100%;max-height:100vh;border-radius:0!important}\r\n.set{padding:16px 12px!important}\r\n.set .two{grid-template-columns:1fr!important;gap:12px}\r\n.chart-box{padding:16px 12px!important}\r\n.chart-bars{gap:4px;min-width:520px;height:160px;padding-top:20px}\r\n.bar-fill{max-width:16px}\r\n}\r\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<!-- Hidden by default: no flicker/clipback when reloading while logged in -->\r\n<section id=\"login\" class=\"hide\">\r\n  <div class=\"lcard\">\r\n    <div class=\"logo\"><div class=\"mark\" id=\"lMark\"></div><span id=\"lName\">Relay Gateway</span></div>\r\n    <h1>Admin login</h1>\r\n    <p>Masuk untuk mengelola client dan akses relay.</p>\r\n    <label for=\"em\">Email</label><input id=\"em\" type=\"email\" placeholder=\"admin@example.com\" autocomplete=\"username\">\r\n    <label for=\"pw\">Password</label><input id=\"pw\" type=\"password\" placeholder=\"Password\" autocomplete=\"current-password\">\r\n    <button class=\"btn full\" id=\"go\"></button>\r\n  </div>\r\n</section>\r\n\r\n<div id=\"app\" class=\"hide\">\r\n  <header class=\"mbar\">\r\n    <div class=\"logo\"><div class=\"mark\" id=\"mMark\"></div><span id=\"mName\">Relay Gateway</span></div>\r\n    <button class=\"btn ghost sm icon-only\" id=\"mOut\" type=\"button\" title=\"Log out\" aria-label=\"Log out\"></button>\r\n  </header>\r\n  <aside>\r\n    <div class=\"logo\"><div class=\"mark\" id=\"sMark\"></div><span id=\"sName\">Relay Gateway</span></div>\r\n    <button class=\"nav on\" data-v=\"clients\" id=\"navClients\"></button>\r\n    <button class=\"nav\" data-v=\"targets\" id=\"navTargets\"></button>\r\n    <button class=\"nav\" data-v=\"logs\" id=\"navLogs\"></button>\r\n    <button class=\"nav\" data-v=\"settings\" id=\"navSettings\"></button>\r\n    <div class=\"spacer\"></div>\r\n    <button class=\"nav out\" id=\"out\"></button>\r\n  </aside>\r\n  <main id=\"main\"></main>\r\n</div>\r\n\r\n<div id=\"toast\"></div>\r\n\r\n<script>\r\nconst $=(s,r=document)=>r.querySelector(s);\r\nconst esc=s=>String(s||\"\").replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\r\nconst rnd=n=>Array.from(crypto.getRandomValues(new Uint8Array(n)),b=>\"abcdefghijkmnpqrstuvwxyz23456789\"[b%32]).join(\"\");\r\n\r\nconst vault = window.secretVault = window.secretVault || {};\r\n\r\nfunction getViewFromPath() {\r\n  const p = window.location.pathname.toLowerCase();\r\n  if (p.includes(\"logs\") || p.includes(\"analytics\")) return \"logs\";\r\n  if (p.includes(\"targets\")) return \"targets\";\r\n  if (p.includes(\"settings\")) return \"settings\";\r\n  return \"clients\";\r\n}\r\n\r\nconst state={\r\n  view: getViewFromPath(),\r\n  settingsTab: \"branding\",\r\n  clients: [],\r\n  global: [],\r\n  settings: { appName:\"Relay Gateway\", logoUrl:\"\", theme:\"auto\", targetRestrict:false, adminEmail:\"\", cfAccountId:\"\", cfApiToken:\"\", hasCfToken:false, cfTokenSource:\"none\" },\r\n  analytics: { configured:true, totalRequests:0, totalErrors:0, avgDurationMs:0, successRate:\"100.0\", hourly:[], logs:[] }\r\n};\r\n\r\n// --- Modern SVG Icons ---\r\nconst icons={\r\n  relay:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12h12M12 6l6 6-6 6\"/></svg>`,\r\n  clients:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"9\" cy=\"8\" r=\"3.5\"/><path d=\"M2.5 20c.6-3.6 3.2-5.5 6.5-5.5s5.9 1.9 6.5 5.5M16 4.8a3.5 3.5 0 010 6.4M21.5 20c-.3-2.4-1.4-4-3.2-4.8\"/></svg>`,\r\n  targets:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c2.5 2.7 3.8 5.7 3.8 9s-1.3 6.3-3.8 9c-2.5-2.7-3.8-5.7-3.8-9S9.5 5.7 12 3z\"/></svg>`,\r\n  logs:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/><polyline points=\"10 9 9 9 8 9\"/></svg>`,\r\n  analytics:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 20V10M12 20V4M6 20v-6\"/></svg>`,\r\n  settings:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M4.9 19.1L7 17M17 7l2.1-2.1\"/></svg>`,\r\n  logout:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 4H5v16h4M16 8l4 4-4 4M20 12H9\"/></svg>`,\r\n  view:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>`,\r\n  edit:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>`,\r\n  power:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18.36 6.64a9 9 0 11-12.73 0M12 2v10\"/></svg>`,\r\n  save:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z\"/><polyline points=\"17 21 17 13 7 13 7 21\"/><polyline points=\"7 3 7 8 15 8\"/></svg>`,\r\n  delete:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2\"/></svg>`,\r\n  copy:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1\"/></svg>`,\r\n  rotate:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21.5 2v6h-6M21.34 15.57a10 10 0 11-.57-8.38l5.67-5.67\"/></svg>`,\r\n  close:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>`,\r\n  plus:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>`,\r\n  spinner:`<svg class=\"spin\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><circle cx=\"12\" cy=\"12\" r=\"9\" stroke-opacity=\".2\"/><path d=\"M12 3a9 9 0 019 9\" stroke-linecap=\"round\"/></svg>`,\r\n  eye:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>`,\r\n  palette:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"13.5\" cy=\"6.5\" r=\".5\"/><circle cx=\"17.5\" cy=\"10.5\" r=\".5\"/><circle cx=\"8.5\" cy=\"7.5\" r=\".5\"/><circle cx=\"6.5\" cy=\"12.5\" r=\".5\"/><path d=\"M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.9 0 1.6-.7 1.6-1.6 0-.4-.2-.8-.5-1.1-.3-.3-.4-.7-.4-1.1 0-.9.7-1.6 1.6-1.6H16c3.3 0 6-2.7 6-6 0-5.5-4.5-10-10-10z\"/></svg>`,\r\n  shield:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>`,\r\n  cloud:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M18 10h-1.26A8 8 0 109 20h9a5 5 0 000-10z\"/></svg>`,\r\n  user:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>`,\r\n  refresh:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M23 4v6h-6M1 20v-6h6M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15\"/></svg>`,\r\n  monitor:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\" ry=\"2\"/><line x1=\"8\" y1=\"21\" x2=\"16\" y2=\"21\"/><line x1=\"12\" y1=\"17\" x2=\"12\" y2=\"21\"/></svg>`,\r\n  sun:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\"/><line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\"/><line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\"/><line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\"/><line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\"/><line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\"/><line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\"/><line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\"/></svg>`,\r\n  moon:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z\"/></svg>`,\r\n  chevronLeft:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"15 18 9 12 15 6\"/></svg>`,\r\n  chevronRight:`<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"9 18 15 12 9 6\"/></svg>`\r\n};\r\n\r\nfunction toast(t){const e=$(\"#toast\");e.textContent=t;e.classList.add(\"show\");clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove(\"show\"),2400)}\r\n\r\nasync function copyText(text, msg = \"Tersalin ke clipboard!\") {\r\n  try {\r\n    await navigator.clipboard.writeText(text);\r\n    toast(msg);\r\n  } catch {\r\n    const ta = document.createElement(\"textarea\");\r\n    ta.value = text;\r\n    document.body.appendChild(ta);\r\n    ta.select();\r\n    document.execCommand(\"copy\");\r\n    ta.remove();\r\n    toast(msg);\r\n  }\r\n}\r\n\r\nasync function api(path,opts={}){\r\n  opts.headers={\"Content-Type\":\"application/json\",...(opts.headers||{})};\r\n  if(opts.body&&typeof opts.body!==\"string\")opts.body=JSON.stringify(opts.body);\r\n  const res=await fetch(path,opts);\r\n  if(res.status===401&&!path.startsWith(\"/api/auth/login\")){\r\n    showLogin();\r\n    throw new Error(\"Unauthorized\");\r\n  }\r\n  const data=await res.json().catch(()=>({}));\r\n  if(!res.ok)throw new Error(data.error||\"Request failed\");\r\n  return data;\r\n}\r\n\r\nfunction showLogin(updateUrl = true){\r\n  $(\"#login\").classList.remove(\"hide\");\r\n  $(\"#app\").classList.add(\"hide\");\r\n  if(updateUrl && window.location.pathname !== \"/login\"){\r\n    window.location.href = \"/login\";\r\n  }\r\n}\r\nfunction showApp(){ $(\"#login\").classList.add(\"hide\"); $(\"#app\").classList.remove(\"hide\"); }\r\n\r\nfunction setFavicon(url){\r\n  let link = document.querySelector(\"link[rel*='icon']\");\r\n  if(!link){\r\n    link = document.createElement(\"link\");\r\n    link.rel = \"icon\";\r\n    document.head.appendChild(link);\r\n  }\r\n  const newLink = link.cloneNode(true);\r\n  newLink.id = \"dynamicFavicon\";\r\n  newLink.href = url;\r\n  if(link.parentNode) link.parentNode.replaceChild(newLink, link);\r\n}\r\n\r\nfunction applyBranding(){\r\n  const name = state.settings.appName || \"Relay Gateway\";\r\n  document.title = name;\r\n  const lName = $(\"#lName\"); if(lName) lName.textContent = name;\r\n  const mName = $(\"#mName\"); if(mName) mName.textContent = name;\r\n  const sName = $(\"#sName\"); if(sName) sName.textContent = name;\r\n\r\n  const logo = state.settings.logoUrl;\r\n  const marks = [$(\"#lMark\"), $(\"#mMark\"), $(\"#sMark\")];\r\n  marks.forEach(m => {\r\n    if(!m) return;\r\n    if(logo){\r\n      m.classList.add(\"has-logo\");\r\n      m.innerHTML = `<img src=\"${esc(logo)}\" class=\"logo-img\" alt=\"logo\">`;\r\n    }else{\r\n      m.classList.remove(\"has-logo\");\r\n      m.innerHTML = icons.relay;\r\n    }\r\n  });\r\n\r\n  const faviconUrl = logo || \"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%233b5bfd' stroke-width='2.2'><path d='M4 12h12M12 6l6 6-6 6'/></svg>\";\r\n  setFavicon(faviconUrl);\r\n}\r\n\r\nasync function syncAll(){\r\n  try{\r\n    const [clients,targets,settings]=await Promise.all([\r\n      api(\"/api/clients\"),\r\n      api(\"/api/targets\"),\r\n      api(\"/api/settings\")\r\n    ]);\r\n    state.clients=clients;\r\n    state.global=targets;\r\n    state.settings=settings;\r\n    applyBranding();\r\n    \r\n    if(state.view===\"logs\" || state.view===\"analytics\") await loadAnalytics();\r\n\r\n    render();\r\n  }catch(err){\r\n    toast(\"Gagal memuat: \"+err.message);\r\n  }\r\n}\r\n\r\nasync function loadAnalytics(){\r\n  try{\r\n    state.analytics = await api(\"/api/analytics\");\r\n  }catch(e){\r\n    state.analytics = { configured: false, error: e.message, logs: [] };\r\n  }\r\n}\r\n\r\nasync function navigate(view, updateUrl = true){\r\n  state.view = view;\r\n  if(updateUrl){\r\n    window.history.pushState({ view }, \"\", \"/dashboard/\" + view);\r\n  }\r\n  if(view === \"logs\" || view === \"analytics\") await loadAnalytics();\r\n  render();\r\n}\r\n\r\nwindow.addEventListener(\"popstate\", async () => {\r\n  const p = window.location.pathname.toLowerCase();\r\n  if(p.includes(\"login\")){\r\n    showLogin(false);\r\n    return;\r\n  }\r\n  state.view = getViewFromPath();\r\n  if(state.view === \"logs\" || state.view === \"analytics\") await loadAnalytics();\r\n  render();\r\n});\r\n\r\nfunction render(){\r\n  document.querySelectorAll(\".nav[data-v]\").forEach(b=>b.classList.toggle(\"on\",b.dataset.v===state.view));\r\n  $(\"#main\").innerHTML=({clients:vClients,targets:vTargets,logs:vLogs,analytics:vLogs,settings:vSettings})[state.view]();\r\n  if(state.view===\"settings\"){\r\n    setTimeout(updateTabArrows, 50);\r\n  }\r\n  if(state.view===\"logs\" || state.view===\"analytics\"){\r\n    setTimeout(() => {\r\n      const cw = $(\".chart-scroll-wrap\");\r\n      if(cw) cw.scrollLeft = cw.scrollWidth;\r\n    }, 50);\r\n  }\r\n  window.scrollTo(0,0);\r\n}\r\n\r\n// --- View: Clients ---\r\nfunction vClients(){\r\n  const a=state.clients.filter(c=>c.status).length;\r\n  const rows=state.clients.map(c=>{\r\n    const m=[];\r\n    if(c.ips&&c.ips.length) m.push(`<span class=\"chip\">IP (${c.ips.length})</span>`);\r\n    if(c.pass) m.push(`<span class=\"chip\">Password</span>`);\r\n    if(c.key) m.push(`<span class=\"chip\">API Key</span>`);\r\n    const chipHtml = m.join(\"\") || '<span class=\"id\">None</span>';\r\n\r\n    return `<div class=\"row\">\r\n     <div><div class=\"name\">${esc(c.name)}</div><div class=\"id\">${c.id}</div></div>\r\n     <div class=\"chips\">${chipHtml}${m.length>1?`<span class=\"chip logic\">${c.logic}</span>`:\"\"}</div>\r\n     <div>${c.restrict?(c.targets?c.targets.length:0)+\" targets\":'<span class=\"id\">Global</span>'}</div>\r\n     <div><span class=\"badge ${c.status?\"on\":\"off\"}\">${c.status?\"Active\":\"Disabled\"}</span></div>\r\n     <div class=\"acts\">\r\n       <button class=\"btn ghost sm icon-only\" data-view=\"${c.id}\" title=\"View Credentials & URLs\" aria-label=\"View\">${icons.view}</button>\r\n       <button class=\"btn ghost sm icon-only\" data-edit=\"${c.id}\" title=\"Edit Client\" aria-label=\"Edit\">${icons.edit}</button>\r\n       <button class=\"btn danger sm icon-only\" data-del=\"${c.id}\" title=\"Delete Client\" aria-label=\"Delete\">${icons.delete}</button>\r\n     </div></div>`;\r\n  }).join(\"\");\r\n\r\n  return `<div class=\"top\">\r\n    <div><h2>Clients</h2><p class=\"sub\">Kelola client, autentikasi, dan aturan relay.</p></div>\r\n    <button class=\"btn addc\" data-edit=\"new\">${icons.plus} Add client</button>\r\n  </div>\r\n  <div class=\"kpis\">\r\n   <div class=\"card kpi\"><b>${state.clients.length}</b><span>Clients</span></div>\r\n   <div class=\"card kpi\"><b>${a}</b><span>Active</span></div>\r\n   <div class=\"card kpi\"><b>${state.clients.reduce((n,c)=>n+(c.ips?c.ips.length:0),0)}</b><span>Whitelisted IPs</span></div>\r\n   <div class=\"card kpi\"><b>${state.global.length}</b><span>Global targets</span></div></div>\r\n  <div class=\"card\">\r\n    <div class=\"row head\"><div>Name</div><div>Access</div><div>Targets</div><div>Status</div><div style=\"text-align:right\">Actions</div></div>\r\n    ${rows||'<div class=\"empty\">Belum ada client. Klik Add client untuk membuat yang pertama.</div>'}\r\n    <div class=\"note\">Statistik dan log request realtime dapat dipantau di menu <a href=\"#\" onclick=\"event.preventDefault();navigate('logs');\">Logs</a>.</div>\r\n  </div>`;\r\n}\r\n\r\n// --- View: Targets ---\r\nfunction vTargets(){\r\n  return `<div class=\"top\"><div><h2>Target whitelist</h2><p class=\"sub\">Tujuan upstream yang diizinkan relay.</p></div></div>\r\n  <div class=\"card\">\r\n    <div class=\"addbar\"><input id=\"nt\" type=\"text\" placeholder=\"api.openai.com\" aria-label=\"Target host\"><button class=\"btn\" id=\"addT\">${icons.plus} Add target</button></div>\r\n    ${state.global.map((t,i)=>`<div class=\"trow\"><span>${esc(t)}</span><button class=\"btn danger sm icon-only\" data-rt=\"${i}\" title=\"Remove target\" aria-label=\"Remove\">${icons.delete}</button></div>`).join(\"\")||'<div class=\"empty\">Daftar kosong. Tambahkan domain tujuan di atas.</div>'}\r\n  </div>`;\r\n}\r\n\r\n// --- View: Logs ---\r\nfunction vLogs(){\r\n  const an = state.analytics;\r\n  const logs = an.logs || [];\r\n\r\n  let errorBanner = \"\";\r\n  if(an.error){\r\n    errorBanner = `<div class=\"card\" style=\"padding:16px 20px;border:1px solid var(--bad);background:var(--bad-s);margin-bottom:18px\">\r\n      <div style=\"font-weight:700;color:var(--bad);margin-bottom:4px\">Koneksi Cloudflare API Bermasalah</div>\r\n      <div style=\"font-size:13px;color:var(--bad);margin-bottom:12px\">${esc(an.error)}</div>\r\n      <button class=\"btn danger sm\" id=\"goAnalyticsSet\">${icons.settings} Periksa Pengaturan Token</button>\r\n    </div>`;\r\n  }\r\n\r\n  const hourly = an.hourly || [];\r\n  const maxReq = Math.max(...hourly.map(h => h.requests), 5);\r\n  \r\n  const barsHtml = hourly.length ? hourly.map(h => {\r\n    const pct = h.requests > 0 ? Math.min(100, Math.max(8, Math.round((h.requests / maxReq) * 100))) : 0;\r\n    const timeStr = h.hour ? new Date(h.hour).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }) : \"\";\r\n    return `<div class=\"bar-col\">\r\n      <div class=\"tooltip\">${timeStr}: ${h.requests} req (${h.errors} err)</div>\r\n      <div class=\"bar-fill ${h.errors > 0 ? 'err' : ''}\" style=\"height:${pct}%\"></div>\r\n      <span class=\"bar-time\">${timeStr}</span>\r\n    </div>`;\r\n  }).join(\"\") : `<div class=\"empty\" style=\"width:100%\">Belum ada aktivitas tercatat dalam 24 jam terakhir.</div>`;\r\n\r\n  // Render Log Table Rows\r\n  const logRows = logs.length ? logs.map(l => {\r\n    const time = new Date(l.timestamp).toLocaleTimeString();\r\n    const isOk = l.status >= 200 && l.status < 400;\r\n    const statusBadge = isOk\r\n      ? `<span class=\"badge on\">${l.status}</span>`\r\n      : `<span class=\"badge\" style=\"background:var(--bad-s);color:var(--bad)\">${l.status}</span>`;\r\n    \r\n    return `<tr>\r\n      <td style=\"color:var(--mute);white-space:nowrap\">${time}</td>\r\n      <td style=\"font-weight:600\">${esc(l.clientName || l.clientId)}</td>\r\n      <td><span class=\"chip\" style=\"font-weight:700;font-size:11px\">${esc(l.method)}</span></td>\r\n      <td>\r\n        <span style=\"font-weight:600\">${esc(l.targetHost)}</span>\r\n        <span class=\"id\" style=\"display:block;max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">${esc(l.targetPath)}</span>\r\n      </td>\r\n      <td>${statusBadge}</td>\r\n      <td style=\"text-align:right;white-space:nowrap;color:var(--mute)\">${l.durationMs}ms</td>\r\n    </tr>`;\r\n  }).join(\"\") : `<tr><td colspan=\"6\" class=\"empty\">Belum ada request relay yang tercatat. Kirim request pertama melalui endpoint relay untuk melihat log di sini.</td></tr>`;\r\n\r\n  return `<div class=\"top\">\r\n    <div><h2>Request Logs</h2><p class=\"sub\">Aktivitas dan riwayat request relay secara realtime.</p></div>\r\n    <div style=\"display:flex;gap:8px\">\r\n      <button class=\"btn ghost sm\" id=\"refreshAn\">${icons.refresh} Refresh</button>\r\n    </div>\r\n  </div>\r\n  ${errorBanner}\r\n  <div class=\"kpis\">\r\n   <div class=\"card kpi\"><b>${(an.totalRequests||0).toLocaleString()}</b><span>Total Requests</span></div>\r\n   <div class=\"card kpi\"><b style=\"color:var(--ok)\">${an.successRate||\"100.0\"}%</b><span>Success Rate</span></div>\r\n   <div class=\"card kpi\"><b style=\"color:${(an.totalErrors||0)>0?'var(--bad)':'inherit'}\">${(an.totalErrors||0).toLocaleString()}</b><span>Errors</span></div>\r\n   <div class=\"card kpi\"><b>${an.avgDurationMs ? an.avgDurationMs + 'ms' : '0ms'}</b><span>Avg Duration</span></div>\r\n  </div>\r\n  <div class=\"card chart-box\">\r\n    <div style=\"font-weight:700;margin-bottom:4px\">Trafik Relay per Jam (24 Jam)</div>\r\n    <div style=\"font-size:12px;color:var(--mute)\">Grafik visual akumulasi request relay yang tercatat</div>\r\n    <div class=\"chart-scroll-wrap\">\r\n      <div class=\"chart-bars\">${barsHtml}</div>\r\n    </div>\r\n  </div>\r\n  \r\n  <!-- Live Request Logs Section -->\r\n  <div class=\"card\" style=\"margin-top:20px;overflow:hidden\">\r\n    <div style=\"padding:16px 20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center\">\r\n      <div>\r\n        <div style=\"font-weight:700;font-size:15px\">Live Request Logs</div>\r\n        <div style=\"font-size:12px;color:var(--mute)\">Riwayat request relay: metode, target host/path, status, dan latensi</div>\r\n      </div>\r\n      <div style=\"display:flex;align-items:center;gap:8px\">\r\n        <span class=\"chip\" style=\"background:var(--ok-s);color:var(--ok);font-size:11px\">${logs.length} Log</span>\r\n        ${logs.length ? `<button class=\"btn danger sm icon-only\" id=\"clearLogsBtn\" title=\"Hapus semua log\" aria-label=\"Hapus log\">${icons.delete}</button>` : ''}\r\n      </div>\r\n    </div>\r\n    <div class=\"log-table-wrap\">\r\n      <table class=\"log-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>Time</th>\r\n            <th>Client</th>\r\n            <th>Method</th>\r\n            <th>Target URL</th>\r\n            <th>Status</th>\r\n            <th style=\"text-align:right\">Duration</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          ${logRows}\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </div>`;\r\n}\r\n\r\n// --- View: Settings (with Tabs) ---\r\nfunction vSettings(){\r\n  const tab = state.settingsTab || \"branding\";\r\n  const st = state.settings;\r\n  const th = st.theme || \"auto\";\r\n\r\n  let tokenStatusBadge = `<span class=\"badge off\">Belum Dikonfigurasi</span>`;\r\n  if(st.hasCfToken){\r\n    if(st.tokenVerified === true){\r\n      tokenStatusBadge = `<span class=\"badge on\">Aktif & Siap Build (${st.cfTokenSource === 'env' ? 'Secret' : 'KV'})</span>`;\r\n    } else if(st.tokenVerified === false){\r\n      tokenStatusBadge = `<span class=\"badge\" style=\"background:var(--bad-s);color:var(--bad);font-weight:700\">Di-revoke / Invalid</span>`;\r\n    } else {\r\n      tokenStatusBadge = `<span class=\"badge on\">Tersimpan (${st.cfTokenSource === 'env' ? 'Secret' : 'KV'})</span>`;\r\n    }\r\n  }\r\n\r\n  let tokenAlertHtml = \"\";\r\n  if(st.hasCfToken && st.tokenVerified === false){\r\n    tokenAlertHtml = `<div class=\"card\" style=\"padding:14px 18px;border:1px solid var(--bad);background:var(--bad-s);margin-bottom:16px\">\r\n      <div style=\"font-weight:700;color:var(--bad);font-size:13.5px\">⚠️ Peringatan: Token Di-revoke di Cloudflare!</div>\r\n      <div style=\"font-size:12.5px;color:var(--bad);margin-top:3px\">${esc(st.tokenStatusMsg || \"Token ini sudah tidak aktif di Cloudflare. Jika Anda melakukan git push atau update repo, build otomatis akan GAGAL!\")}</div>\r\n    </div>`;\r\n  } else if(st.hasCfToken && st.tokenVerified === true){\r\n    tokenAlertHtml = `<div class=\"card\" style=\"padding:12px 16px;border:1px solid var(--ok);background:var(--ok-s);margin-bottom:16px\">\r\n      <div style=\"font-weight:700;color:var(--ok);font-size:13px\">✓ Token Terverifikasi Aktif</div>\r\n      <div style=\"font-size:12px;color:var(--ok);margin-top:2px\">Token Cloudflare valid. Update repo dan deploy berikutnya akan berjalan normal.</div>\r\n    </div>`;\r\n  }\r\n\r\n  return `<div class=\"top\"><div><h2>Settings</h2><p class=\"sub\">Pengaturan aplikasi, keamanan, dan integrasi.</p></div></div>\r\n  <div class=\"tabs-nav-wrap\">\r\n    <button class=\"tabs-arrow left hide\" id=\"tabArrL\" type=\"button\" aria-label=\"Scroll left\">${icons.chevronLeft}</button>\r\n    <div class=\"tabs\" id=\"settingsTabs\">\r\n      <button class=\"tab ${tab==='branding'?'on':''}\" data-tab=\"branding\">${icons.palette} <span>Branding & Tampilan</span></button>\r\n      <button class=\"tab ${tab==='relay'?'on':''}\" data-tab=\"relay\">${icons.shield} <span>Relay & Keamanan</span></button>\r\n      <button class=\"tab ${tab==='cloudflare'?'on':''}\" data-tab=\"cloudflare\">${icons.cloud} <span>Cloudflare API & Secrets</span></button>\r\n      <button class=\"tab ${tab==='admin'?'on':''}\" data-tab=\"admin\">${icons.user} <span>Akun Admin</span></button>\r\n    </div>\r\n    <button class=\"tabs-arrow right hide\" id=\"tabArrR\" type=\"button\" aria-label=\"Scroll right\">${icons.chevronRight}</button>\r\n  </div>\r\n\r\n  <!-- Tab 1: Branding -->\r\n  <div class=\"tab-pane ${tab==='branding'?'on':''}\" id=\"pane-branding\">\r\n    <div class=\"card set\" style=\"padding:22px\">\r\n      <label style=\"margin-top:0\">App Name</label>\r\n      <input id=\"setAppName\" type=\"text\" value=\"${esc(st.appName)}\" placeholder=\"Relay Gateway\">\r\n      \r\n      <label>Logo / Favicon URL</label>\r\n      <input id=\"setLogoUrl\" type=\"text\" value=\"${esc(st.logoUrl)}\" placeholder=\"https://example.com/logo.png (Opsional)\">\r\n      \r\n      <label>Theme</label>\r\n      <div class=\"seg\" id=\"themeSeg\">\r\n        <button type=\"button\" data-t=\"auto\" class=\"${th==='auto'?'on':''}\">${icons.monitor} <span>System</span></button>\r\n        <button type=\"button\" data-t=\"light\" class=\"${th==='light'?'on':''}\">${icons.sun} <span>Light</span></button>\r\n        <button type=\"button\" data-t=\"dark\" class=\"${th==='dark'?'on':''}\">${icons.moon} <span>Dark</span></button>\r\n      </div>\r\n\r\n      <div class=\"foot\" style=\"margin-top:24px;display:flex;justify-content:flex-end\">\r\n        <button class=\"btn\" id=\"btnSaveBranding\" disabled>${icons.save} Save changes</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Tab 2: Relay & Security -->\r\n  <div class=\"tab-pane ${tab==='relay'?'on':''}\" id=\"pane-relay\">\r\n    <div class=\"card set\" style=\"padding:22px\">\r\n      <div class=\"opt\">\r\n        <div>\r\n          <div>Global Target Restriction</div>\r\n          <div class=\"id\">Hanya izinkan relay ke domain di Target Whitelist jika client tidak memiliki target khusus.</div>\r\n        </div>\r\n        <span class=\"toggle\"><input type=\"checkbox\" id=\"setGtr\" ${st.targetRestrict?'checked':''}><i></i></span>\r\n      </div>\r\n\r\n      <div class=\"foot\" style=\"margin-top:24px;display:flex;justify-content:flex-end\">\r\n        <button class=\"btn\" id=\"btnSaveRelay\" disabled>${icons.save} Save changes</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Tab 3: Cloudflare All-in-One API Token & Credentials -->\r\n  <div class=\"tab-pane ${tab==='cloudflare'?'on':''}\" id=\"pane-cloudflare\">\r\n    <div class=\"card set\" style=\"padding:22px\">\r\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:14px\">\r\n        <div>\r\n          <div style=\"font-weight:700\">Cloudflare API & Secrets (All-in-One)</div>\r\n          <div class=\"id\">ID Akun dan API Token Cloudflare untuk build & integrasi client.</div>\r\n        </div>\r\n        ${tokenStatusBadge}\r\n      </div>\r\n\r\n      ${tokenAlertHtml}\r\n      \r\n      <label style=\"margin-top:0\">Cloudflare Account ID</label>\r\n      <div class=\"inline\">\r\n        <input id=\"setCfAcc\" type=\"text\" value=\"${esc(st.cfAccountId || '')}\" placeholder=\"Masukkan Account ID Cloudflare\">\r\n        <button class=\"btn sm\" id=\"cpCfAccBtn\" type=\"button\" ${st.cfAccountId ? '' : 'disabled'}>${icons.copy} Copy</button>\r\n      </div>\r\n\r\n      <label>Cloudflare All-in-One API Token Secret</label>\r\n      <div class=\"inline\" style=\"position:relative\">\r\n        <div class=\"input-wrap\" style=\"flex:1\">\r\n          <input id=\"setCfTok\" type=\"password\" value=\"${esc(st.cfApiToken || '')}\" placeholder=\"Masukkan Cloudflare All-in-One API Token\">\r\n          <button class=\"btn-eye\" id=\"toggleTokEye\" type=\"button\" aria-label=\"Toggle token\">${icons.eye}</button>\r\n        </div>\r\n        <button class=\"btn sm\" id=\"cpCfTokBtn\" type=\"button\" ${st.cfApiToken ? '' : 'disabled'}>${icons.copy} Copy</button>\r\n      </div>\r\n      <div class=\"id\" style=\"margin-top:8px\">Setelah membuat atau me-revoke token baru di dashboard Cloudflare, simpan di sini agar aplikasi tetap sinkron dan token siap disalin kapan saja.</div>\r\n\r\n      <div class=\"foot\" style=\"margin-top:20px;display:flex;justify-content:space-between;align-items:center\">\r\n        <button class=\"btn ghost sm\" id=\"btnTestCf\" type=\"button\" ${st.cfApiToken ? '' : 'disabled'}>${icons.refresh} <span>Verifikasi Status Token</span></button>\r\n        <button class=\"btn\" id=\"btnSaveCf\" disabled>${icons.save} Save changes</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Tab 4: Admin Account -->\r\n  <div class=\"tab-pane ${tab==='admin'?'on':''}\" id=\"pane-admin\">\r\n    <div class=\"card set\" style=\"padding:22px\">\r\n      <div class=\"two\" style=\"display:grid;grid-template-columns:1fr 1fr;gap:16px\">\r\n        <div>\r\n          <label style=\"margin-top:0\">Admin email</label>\r\n          <input id=\"setAdminEmail\" type=\"email\" value=\"${esc(st.adminEmail)}\">\r\n        </div>\r\n        <div>\r\n          <label style=\"margin-top:0\">New password</label>\r\n          <input id=\"setAdminPass\" type=\"password\" placeholder=\"Minimal 12 karakter (kosongkan jika tidak ganti)\">\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"foot\" style=\"margin-top:24px;display:flex;justify-content:space-between;align-items:center\">\r\n        <button class=\"btn danger\" id=\"out2\">${icons.logout} Log out</button>\r\n        <button class=\"btn\" id=\"btnSaveAdmin\" disabled>${icons.save} Save changes</button>\r\n      </div>\r\n    </div>\r\n  </div>`;\r\n}\r\n\r\nfunction updateTabArrows(){\r\n  const el = $(\"#settingsTabs\");\r\n  const arrL = $(\"#tabArrL\");\r\n  const arrR = $(\"#tabArrR\");\r\n  if(!el || !arrL || !arrR) return;\r\n  const canL = el.scrollLeft > 4;\r\n  const canR = el.scrollLeft + el.clientWidth < el.scrollWidth - 4;\r\n  arrL.classList.toggle(\"hide\", !canL);\r\n  arrR.classList.toggle(\"hide\", !canR);\r\n}\r\n\r\n// --- Action View Drawer (Modal Khusus Copy Kredensial & URL) ---\r\nfunction viewDrawer(id){\r\n  const c = state.clients.find(x => x.id === id);\r\n  if(!c) return;\r\n\r\n  const origin = window.location.origin;\r\n  const rawKey = vault[c.id]?.key || c.key;\r\n  const rawPass = vault[c.id]?.pass || null;\r\n\r\n  // Path Prefix URL\r\n  const pathUrl = (c.pass && !c.key)\r\n    ? `${origin}/p/${rawPass || 'password123'}`\r\n    : `${origin}/${rawKey || 'relay_key'}`;\r\n\r\n  // Query Param URL\r\n  const queryUrl = (c.pass && !c.key)\r\n    ? `${origin}/?pass=${rawPass || 'password123'}`\r\n    : `${origin}/?key=${rawKey || 'relay_key'}`;\r\n\r\n  // Snippet Header\r\n  const targetExample = (c.targets && c.targets.length) ? (\"https://\" + c.targets[0]) : \"https://api.openai.com\";\r\n  let hdrSnippet = `POST / HTTP/1.1\\nx-relay-target: ${targetExample}\\nx-relay-path: /v1/chat/completions\\n`;\r\n  if(c.key) hdrSnippet += `x-relay-api-key: ${rawKey || 'relay_key'}\\n`;\r\n  if(c.pass) hdrSnippet += `x-relay-password: ${rawPass || '••••••••'}\\n`;\r\n  hdrSnippet += `Authorization: Bearer <upstream_token_anda>`;\r\n\r\n  const el = document.createElement(\"div\");\r\n  el.className = \"scrim\";\r\n  document.body.appendChild(el);\r\n  document.body.classList.add(\"modal-open\");\r\n\r\n  const close = () => {\r\n    document.body.classList.remove(\"modal-open\");\r\n    el.remove();\r\n  };\r\n  el.addEventListener(\"click\", e => { if(e.target === el) close(); });\r\n\r\n  el.innerHTML = `<div class=\"drawer\" role=\"dialog\" aria-label=\"View Client\">\r\n    <div class=\"drawer-head\">\r\n      <div>\r\n        <h2 style=\"font-size:18px\">${esc(c.name)}</h2>\r\n        <div class=\"id\">${c.id} • ${c.status ? '<span style=\"color:var(--ok)\">Active</span>' : '<span style=\"color:var(--mute)\">Disabled</span>'}</div>\r\n      </div>\r\n      <button class=\"btn ghost sm icon-only\" id=\"vwClose\" type=\"button\" aria-label=\"Close\">${icons.close}</button>\r\n    </div>\r\n\r\n    <div class=\"drawer-body\">\r\n      <!-- Credentials -->\r\n      <div style=\"font-weight:700;margin-bottom:8px\">Kredensial Client</div>\r\n      \r\n      ${c.key ? `<div class=\"url-card\">\r\n        <div class=\"title\">API Key</div>\r\n        <div class=\"inline\">\r\n          <input type=\"text\" readonly id=\"vwKeyVal\" value=\"${esc(rawKey || (c.key + '••••••••••'))}\">\r\n          <button class=\"btn sm\" id=\"cpKeyBtn\" type=\"button\">${icons.copy} Copy</button>\r\n        </div>\r\n      </div>` : ''}\r\n\r\n      ${c.pass ? `<div class=\"url-card\">\r\n        <div class=\"title\">Password</div>\r\n        <div class=\"inline\">\r\n          <input type=\"text\" readonly id=\"vwPassVal\" value=\"${esc(rawPass || '•••••••• (Tersimpan sebagai hash)')}\">\r\n          <button class=\"btn sm\" id=\"cpPassBtn\" type=\"button\" ${rawPass ? '' : 'disabled'}>${icons.copy} Copy</button>\r\n        </div>\r\n        ${rawPass ? '' : '<div class=\"id\" style=\"margin-top:4px\">Gunakan Reset Password di menu Edit jika Anda ingin mengganti password baru.</div>'}\r\n      </div>` : ''}\r\n\r\n      ${!c.key && !c.pass ? `<div class=\"id\" style=\"margin-bottom:12px\">Client ini menggunakan autentikasi <b>IP Whitelist</b> saja.</div>` : ''}\r\n\r\n      <!-- Format URLs -->\r\n      <div class=\"url-card\" style=\"margin-top:14px\">\r\n        <div class=\"title\">Format 1: Path Prefix (Rekomendasi Base URL)</div>\r\n        <div class=\"desc\">Cukup tempelkan ke kolom Base URL / API URL aplikasi client Anda. Subpath diteruskan otomatis.</div>\r\n        <div class=\"inline\">\r\n          <input type=\"text\" readonly id=\"vwFmt1\" value=\"${esc(pathUrl)}\">\r\n          <button class=\"btn sm\" id=\"cpFmt1Btn\" type=\"button\">${icons.copy} Copy</button>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"url-card\">\r\n        <div class=\"title\">Format 2: Query Parameter (?key=... atau ?pass=...)</div>\r\n        <div class=\"desc\">Bisa dipakai jika aplikasi client mempertahankan query string URL saat request.</div>\r\n        <div class=\"inline\">\r\n          <input type=\"text\" readonly id=\"vwFmt2\" value=\"${esc(queryUrl)}\">\r\n          <button class=\"btn sm\" id=\"cpFmt2Btn\" type=\"button\">${icons.copy} Copy</button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Header snippet -->\r\n      <div class=\"url-card\">\r\n        <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\r\n          <div class=\"title\" style=\"margin:0\">Opsi Alternatif: Kirim via HTTP Header</div>\r\n          <button class=\"btn ghost sm\" id=\"cpHdrBtn\" type=\"button\">${icons.copy} Copy</button>\r\n        </div>\r\n        <pre style=\"margin:0;font-family:ui-monospace,Menlo,monospace;font-size:11.5px;color:var(--ink);background:var(--bg);border:1px solid var(--line);padding:10px;border-radius:8px;overflow-x:auto\">${esc(hdrSnippet)}</pre>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"drawer-foot\">\r\n      <button class=\"btn ghost\" id=\"vwFootClose\" type=\"button\">${icons.close} Tutup</button>\r\n    </div>\r\n  </div>`;\r\n\r\n  const g = s => $(s, el);\r\n  g(\"#vwClose\").onclick = close;\r\n  g(\"#vwFootClose\").onclick = close;\r\n\r\n  if(g(\"#cpKeyBtn\")) g(\"#cpKeyBtn\").onclick = () => copyText(rawKey || c.key, \"API Key disalin!\");\r\n  if(g(\"#cpPassBtn\") && rawPass) g(\"#cpPassBtn\").onclick = () => copyText(rawPass, \"Password disalin!\");\r\n  g(\"#cpFmt1Btn\").onclick = () => copyText(pathUrl, \"Base URL (Path Prefix) disalin!\");\r\n  g(\"#cpFmt2Btn\").onclick = () => copyText(queryUrl, \"URL (Query Param) disalin!\");\r\n  g(\"#cpHdrBtn\").onclick = () => copyText(hdrSnippet, \"Header snippet disalin!\");\r\n}\r\n\r\n// --- Edit / Create Drawer ---\r\nfunction editDrawer(id){\r\n  const isNew = id === \"new\";\r\n  const c = isNew\r\n    ? { id: \"new\", name: \"\", status: true, logic: \"ANY\", ips: [], pass: false, key: null, restrict: false, targets: [] }\r\n    : JSON.parse(JSON.stringify(state.clients.find(x => x.id === id)));\r\n\r\n  let willGenPass = false, willGenKey = false;\r\n  let newPassPlain = null, newKeyPlain = null;\r\n  let useIp = (c.ips && c.ips.length > 0) || isNew;\r\n  let usePass = !!c.pass;\r\n  let useKey = !!c.key;\r\n  let isDirty = false;\r\n\r\n  const el = document.createElement(\"div\");\r\n  el.className = \"scrim\";\r\n  document.body.appendChild(el);\r\n  document.body.classList.add(\"modal-open\");\r\n\r\n  const close = () => {\r\n    document.body.classList.remove(\"modal-open\");\r\n    el.remove();\r\n  };\r\n  el.addEventListener(\"click\", e => { if(e.target === el) close(); });\r\n\r\n  function tagsHtml(arr, k){\r\n    return (arr || []).map((v, i) => `<span class=\"tag\">${esc(v)}<button data-x=\"${k}:${i}\" aria-label=\"Remove ${esc(v)}\">×</button></span>`).join(\"\");\r\n  }\r\n\r\n  el.innerHTML = `<div class=\"drawer\" role=\"dialog\" aria-label=\"Client form\">\r\n    <div class=\"drawer-head\">\r\n      <h2>${isNew ? \"Add client\" : \"Edit \" + esc(c.name)}</h2>\r\n      <button class=\"btn ghost sm icon-only\" id=\"edClose\" type=\"button\" aria-label=\"Close\">${icons.close}</button>\r\n    </div>\r\n\r\n    <div class=\"drawer-body\">\r\n      <label for=\"cn\">Client Name</label>\r\n      <input id=\"cn\" type=\"text\" value=\"${esc(c.name)}\" placeholder=\"Client Name\">\r\n\r\n      <label>Access methods</label>\r\n\r\n      <!-- IP Whitelist (Swift Toggle) -->\r\n      <div class=\"opt\">\r\n        <span>IP whitelist</span>\r\n        <span class=\"toggle\"><input type=\"checkbox\" id=\"mi\" ${useIp ? 'checked' : ''}><i></i></span>\r\n      </div>\r\n      <div class=\"sub-box ${useIp ? '' : 'hide'}\" id=\"boxIp\">\r\n        <div class=\"inline\">\r\n          <input id=\"ip\" type=\"text\" placeholder=\"203.0.113.1\">\r\n          <button class=\"btn sm square-btn\" id=\"addIp\" type=\"button\" title=\"Add IP\" aria-label=\"Add IP\">${icons.plus}</button>\r\n        </div>\r\n        <div class=\"tags\" id=\"listIp\">${tagsHtml(c.ips, \"ip\")}</div>\r\n      </div>\r\n\r\n      <!-- Password (Swift Toggle & Inline Rotate) -->\r\n      <div class=\"opt\">\r\n        <span>Password</span>\r\n        <span class=\"toggle\"><input type=\"checkbox\" id=\"mp\" ${usePass ? 'checked' : ''}><i></i></span>\r\n      </div>\r\n      <div class=\"sub-box ${usePass ? '' : 'hide'}\" id=\"boxPass\">\r\n        <div class=\"inline\" style=\"justify-content:space-between;align-items:center;width:100%\">\r\n          <div id=\"secPass\" style=\"flex:1;min-width:0\">\r\n            ${c.pass ? '<div class=\"id\">Password aktif tersimpan sebagai hash.</div>' : ''}\r\n          </div>\r\n          <button class=\"btn ghost sm\" id=\"gp\" type=\"button\" style=\"flex:none\" title=\"Rotate Password\">${icons.rotate} <span>Rotate</span></button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- API Key (Swift Toggle & Inline Rotate) -->\r\n      <div class=\"opt\">\r\n        <span>API key</span>\r\n        <span class=\"toggle\"><input type=\"checkbox\" id=\"mk\" ${useKey ? 'checked' : ''}><i></i></span>\r\n      </div>\r\n      <div class=\"sub-box ${useKey ? '' : 'hide'}\" id=\"boxKey\">\r\n        <div class=\"inline\" style=\"justify-content:space-between;align-items:center;width:100%\">\r\n          <div id=\"secKey\" style=\"flex:1;min-width:0\">\r\n            ${c.key ? `<div class=\"secret-box\" style=\"background:var(--bg);color:var(--mute);margin:0\"><code>${esc(c.key)}••••••••••</code></div>` : ''}\r\n          </div>\r\n          <button class=\"btn ghost sm\" id=\"gk\" type=\"button\" style=\"flex:none\" title=\"Rotate API Key\">${icons.rotate} <span>Rotate</span></button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Auth Logic (Buttons on Left, Text on Right) -->\r\n      <label>Authentication logic</label>\r\n      <div style=\"display:flex;align-items:center;gap:12px;flex-wrap:wrap\">\r\n        <div class=\"seg\" id=\"lg\" style=\"flex:none\">\r\n          <button type=\"button\" data-l=\"ANY\" class=\"${c.logic === \"ANY\" ? \"on\" : \"\"}\">ANY</button>\r\n          <button type=\"button\" data-l=\"ALL\" class=\"${c.logic === \"ALL\" ? \"on\" : \"\"}\">ALL</button>\r\n        </div>\r\n        <div class=\"id\" id=\"logicDesc\" style=\"margin:0;flex:1\">${c.logic === \"ANY\" ? \"Salah satu metode valid sudah cukup.\" : \"Semua metode yang aktif harus valid.\"}</div>\r\n      </div>\r\n\r\n      <!-- Target Restriction (Swift Toggle) -->\r\n      <label>Target restriction</label>\r\n      <div class=\"opt\">\r\n        <span>Batasi target untuk client ini</span>\r\n        <span class=\"toggle\"><input type=\"checkbox\" id=\"tr\" ${c.restrict ? 'checked' : ''}><i></i></span>\r\n      </div>\r\n      <div class=\"sub-box ${c.restrict ? '' : 'hide'}\" id=\"boxTarget\">\r\n        <div class=\"inline\">\r\n          <input id=\"tg\" type=\"text\" placeholder=\"api.xkiro.com\">\r\n          <button class=\"btn sm square-btn\" id=\"addTg\" type=\"button\" title=\"Add Target\" aria-label=\"Add Target\">${icons.plus}</button>\r\n        </div>\r\n        <div class=\"tags\" id=\"listTg\">${tagsHtml(c.targets, \"tg\")}</div>\r\n      </div>\r\n\r\n      <!-- Status Active (Swift Toggle) -->\r\n      <div class=\"opt\" style=\"margin-top:14px\">\r\n        <span>Active</span>\r\n        <span class=\"toggle\"><input type=\"checkbox\" id=\"st\" ${c.status ? 'checked' : ''}><i></i></span>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"drawer-foot\">\r\n      ${isNew ? '' : `<button class=\"btn danger\" id=\"dl\" type=\"button\">${icons.delete} Delete</button>`}\r\n      <button class=\"btn\" id=\"sv\" type=\"button\" disabled>${icons.save} <span id=\"svText\">${isNew ? \"Create client\" : \"Save changes\"}</span></button>\r\n    </div>\r\n  </div>`;\r\n\r\n  const g = s => $(s, el);\r\n  const markDirty = () => {\r\n    isDirty = true;\r\n    g(\"#sv\").disabled = false;\r\n  };\r\n\r\n  g(\"#cn\").oninput = e => { c.name = e.target.value; markDirty(); };\r\n  g(\"#edClose\").onclick = close;\r\n\r\n  // Toggle IP\r\n  g(\"#mi\").onchange = e => {\r\n    useIp = e.target.checked;\r\n    g(\"#boxIp\").classList.toggle(\"hide\", !useIp);\r\n    markDirty();\r\n  };\r\n  g(\"#addIp\").onclick = () => {\r\n    const v = g(\"#ip\").value.trim();\r\n    if(v && !c.ips.includes(v)){\r\n      c.ips.push(v);\r\n      g(\"#ip\").value = \"\";\r\n      g(\"#listIp\").innerHTML = tagsHtml(c.ips, \"ip\");\r\n      bindTagRemoves();\r\n      markDirty();\r\n    }\r\n  };\r\n  g(\"#ip\").onkeydown = e => { if(e.key === \"Enter\"){ e.preventDefault(); g(\"#addIp\").click(); } };\r\n\r\n  // Toggle Password (AUTO-GENERATE saat switch ON)\r\n  g(\"#mp\").onchange = e => {\r\n    usePass = e.target.checked;\r\n    g(\"#boxPass\").classList.toggle(\"hide\", !usePass);\r\n    if(usePass && !c.pass && !newPassPlain){\r\n      willGenPass = true;\r\n      newPassPlain = rnd(20);\r\n      g(\"#secPass\").innerHTML = `<div class=\"secret-box\" style=\"margin:0\"><code>${newPassPlain}</code></div>`;\r\n    }\r\n    markDirty();\r\n  };\r\n  g(\"#gp\").onclick = () => {\r\n    willGenPass = true;\r\n    newPassPlain = rnd(20);\r\n    g(\"#secPass\").innerHTML = `<div class=\"secret-box\" style=\"margin:0\"><code>${newPassPlain}</code></div>`;\r\n    markDirty();\r\n  };\r\n\r\n  // Toggle API Key (AUTO-GENERATE saat switch ON)\r\n  g(\"#mk\").onchange = e => {\r\n    useKey = e.target.checked;\r\n    g(\"#boxKey\").classList.toggle(\"hide\", !useKey);\r\n    if(useKey && !c.key && !newKeyPlain){\r\n      willGenKey = true;\r\n      newKeyPlain = \"relay_\" + rnd(16);\r\n      g(\"#secKey\").innerHTML = `<div class=\"secret-box\" style=\"margin:0\"><code>${newKeyPlain}</code></div>`;\r\n    }\r\n    markDirty();\r\n  };\r\n  g(\"#gk\").onclick = () => {\r\n    willGenKey = true;\r\n    newKeyPlain = \"relay_\" + rnd(16);\r\n    g(\"#secKey\").innerHTML = `<div class=\"secret-box\" style=\"margin:0\"><code>${newKeyPlain}</code></div>`;\r\n    markDirty();\r\n  };\r\n\r\n  // Auth Logic buttons\r\n  el.querySelectorAll(\"[data-l]\").forEach(b => b.onclick = () => {\r\n    c.logic = b.dataset.l;\r\n    el.querySelectorAll(\"[data-l]\").forEach(x => x.classList.toggle(\"on\", x === b));\r\n    g(\"#logicDesc\").textContent = (c.logic === \"ANY\" ? \"Salah satu metode valid sudah cukup.\" : \"Semua metode yang aktif harus valid.\");\r\n    markDirty();\r\n  });\r\n\r\n  // Toggle Target Restriction\r\n  g(\"#tr\").onchange = e => {\r\n    c.restrict = e.target.checked;\r\n    g(\"#boxTarget\").classList.toggle(\"hide\", !c.restrict);\r\n    markDirty();\r\n  };\r\n  g(\"#addTg\").onclick = () => {\r\n    const v = g(\"#tg\").value.trim().toLowerCase();\r\n    if(v && !c.targets.includes(v)){\r\n      c.targets.push(v);\r\n      g(\"#tg\").value = \"\";\r\n      g(\"#listTg\").innerHTML = tagsHtml(c.targets, \"tg\");\r\n      bindTagRemoves();\r\n      markDirty();\r\n    }\r\n  };\r\n  g(\"#tg\").onkeydown = e => { if(e.key === \"Enter\"){ e.preventDefault(); g(\"#addTg\").click(); } };\r\n\r\n  // Toggle Status\r\n  g(\"#st\").onchange = e => { c.status = e.target.checked; markDirty(); };\r\n\r\n  function bindTagRemoves(){\r\n    el.querySelectorAll(\"[data-x]\").forEach(b => b.onclick = () => {\r\n      const [k, i] = b.dataset.x.split(\":\");\r\n      if(k === \"ip\"){\r\n        c.ips.splice(+i, 1);\r\n        g(\"#listIp\").innerHTML = tagsHtml(c.ips, \"ip\");\r\n      }else{\r\n        c.targets.splice(+i, 1);\r\n        g(\"#listTg\").innerHTML = tagsHtml(c.targets, \"tg\");\r\n      }\r\n      bindTagRemoves();\r\n      markDirty();\r\n    });\r\n  }\r\n  bindTagRemoves();\r\n\r\n  // Delete\r\n  if(g(\"#dl\")){\r\n    g(\"#dl\").onclick = async () => {\r\n      if(confirm(`Hapus client \"${c.name}\"?`)){\r\n        try{\r\n          await api(\"/api/clients/\" + c.id, { method: \"DELETE\" });\r\n          delete vault[c.id];\r\n          state.clients = state.clients.filter(x => x.id !== c.id);\r\n          close();\r\n          render();\r\n          toast(\"Client deleted\");\r\n        }catch(err){ toast(\"Gagal: \" + err.message); }\r\n      }\r\n    };\r\n  }\r\n\r\n  // Save (with Spinner and Loading State)\r\n  g(\"#sv\").onclick = async () => {\r\n    if(!c.name.trim()){ toast(\"Isi nama client dulu\"); g(\"#cn\").focus(); return; }\r\n\r\n    const svBtn = g(\"#sv\");\r\n    const origHtml = svBtn.innerHTML;\r\n    svBtn.disabled = true;\r\n    svBtn.innerHTML = `${icons.spinner} <span>Menyimpan...</span>`;\r\n\r\n    const payload = {\r\n      name: c.name.trim(),\r\n      status: c.status,\r\n      logic: c.logic,\r\n      ips: useIp ? c.ips : [],\r\n      restrict: c.restrict,\r\n      targets: c.restrict ? c.targets : []\r\n    };\r\n    if(newPassPlain) payload.newPassword = newPassPlain;\r\n    else if(!usePass && c.pass) payload.removePassword = true;\r\n    if(willGenKey) payload.generateKey = true;\r\n\r\n    try{\r\n      let res;\r\n      if(isNew){\r\n        res = await api(\"/api/clients\", { method: \"POST\", body: payload });\r\n        state.clients.push(res.client);\r\n      }else{\r\n        res = await api(\"/api/clients/\" + c.id, { method: \"PUT\", body: payload });\r\n        state.clients = state.clients.map(x => x.id === c.id ? res.client : x);\r\n      }\r\n\r\n      vault[res.client.id] = vault[res.client.id] || {};\r\n      if(res.rawKey) vault[res.client.id].key = res.rawKey;\r\n      if(res.rawPassword) vault[res.client.id].pass = res.rawPassword;\r\n\r\n      close();\r\n      render();\r\n      toast(isNew ? \"Client created\" : \"Client saved\");\r\n      \r\n      if(res.rawKey || res.rawPassword){\r\n        viewDrawer(res.client.id);\r\n      }\r\n    }catch(err){\r\n      svBtn.disabled = false;\r\n      svBtn.innerHTML = origHtml;\r\n      toast(\"Gagal simpan: \" + err.message);\r\n    }\r\n  };\r\n\r\n  g(\"#cn\").focus();\r\n}\r\n\r\n// Global Click Handlers\r\ndocument.addEventListener(\"click\", async e => {\r\n  const t = e.target.closest(\"button\");\r\n  if(!t) return;\r\n\r\n  // Navigations\r\n  if(t.dataset.v){\r\n    navigate(t.dataset.v);\r\n  }\r\n  // Action View\r\n  else if(t.dataset.view) viewDrawer(t.dataset.view);\r\n  // Edit Client\r\n  else if(t.dataset.edit) editDrawer(t.dataset.edit);\r\n  // Delete Client directly from row\r\n  else if(t.dataset.del){\r\n    const cid = t.dataset.del;\r\n    const c = state.clients.find(x => x.id === cid);\r\n    if(c && confirm(`Hapus client \"${c.name}\"?`)){\r\n      try{\r\n        await api(\"/api/clients/\" + c.id, { method: \"DELETE\" });\r\n        delete vault[c.id];\r\n        state.clients = state.clients.filter(x => x.id !== c.id);\r\n        render();\r\n        toast(\"Client deleted\");\r\n      }catch(err){ toast(\"Gagal: \" + err.message); }\r\n    }\r\n  }\r\n  // Remove Target\r\n  else if(t.dataset.rt){\r\n    const target = state.global[+t.dataset.rt];\r\n    try{\r\n      await api(\"/api/targets/\" + encodeURIComponent(target), { method: \"DELETE\" });\r\n      state.global.splice(+t.dataset.rt, 1);\r\n      render();\r\n      toast(\"Target removed\");\r\n    }catch(err){ toast(\"Gagal: \" + err.message); }\r\n  }\r\n  // Add Target\r\n  else if(t.id === \"addT\"){\r\n    const v = $(\"#nt\").value.trim().toLowerCase();\r\n    if(v){\r\n      try{\r\n        const updated = await api(\"/api/targets\", { method: \"POST\", body: { target: v } });\r\n        state.global = updated;\r\n        render();\r\n        toast(\"Target added\");\r\n      }catch(err){ toast(\"Gagal: \" + err.message); }\r\n    }\r\n  }\r\n  // Refresh Analytics\r\n  else if(t.id === \"refreshAn\"){\r\n    const btn = t;\r\n    btn.disabled = true;\r\n    btn.innerHTML = `${icons.spinner} Loading...`;\r\n    await loadAnalytics();\r\n    render();\r\n    toast(\"Analytics diperbarui\");\r\n  }\r\n  // Clear Logs\r\n  else if(t.closest(\"#clearLogsBtn\")){\r\n    if(confirm(\"Hapus semua log request relay?\")){\r\n      try{\r\n        await api(\"/api/analytics/logs\", { method: \"DELETE\" });\r\n        await loadAnalytics();\r\n        render();\r\n        toast(\"Log request berhasil dibersihkan\");\r\n      }catch(err){ toast(\"Gagal: \" + err.message); }\r\n    }\r\n  }\r\n  // Go to Analytics Settings shortcut\r\n  else if(t.id === \"goAnalyticsSet\"){\r\n    state.settingsTab = \"analytics\";\r\n    navigate(\"settings\");\r\n  }\r\n  // Settings Tab switches\r\n  else if(t.dataset.tab){\r\n    state.settingsTab = t.dataset.tab;\r\n    render();\r\n  }\r\n  // Settings Tab scroll arrows\r\n  else if(t.id === \"tabArrL\"){\r\n    const el = $(\"#settingsTabs\");\r\n    if(el) el.scrollBy({ left: -140, behavior: \"smooth\" });\r\n  }\r\n  else if(t.id === \"tabArrR\"){\r\n    const el = $(\"#settingsTabs\");\r\n    if(el) el.scrollBy({ left: 140, behavior: \"smooth\" });\r\n  }\r\n  // Theme button switches in Tab 1\r\n  else if(t.dataset.t){\r\n    const th = t.dataset.t;\r\n    state.settings.theme = th;\r\n    localStorage.setItem(\"relay_theme\", th);\r\n    document.documentElement.dataset.theme = th === \"auto\" ? \"\" : th;\r\n    t.parentNode.querySelectorAll(\"button\").forEach(b => b.classList.toggle(\"on\", b === t));\r\n    const btn = $(\"#btnSaveBranding\");\r\n    if(btn) btn.disabled = false;\r\n  }\r\n  // Toggle password eye\r\n  else if(t.id === \"toggleTokEye\"){\r\n    const inp = $(\"#setCfTok\");\r\n    if(inp.type === \"password\"){\r\n      inp.type = \"text\";\r\n      t.style.color = \"var(--acc)\";\r\n    }else{\r\n      inp.type = \"password\";\r\n      t.style.color = \"var(--mute)\";\r\n    }\r\n  }\r\n  // Copy Cloudflare Account ID\r\n  else if(t.id === \"cpCfAccBtn\"){\r\n    const v = $(\"#setCfAcc\")?.value || \"\";\r\n    if(v) copyText(v, \"Cloudflare Account ID disalin!\");\r\n  }\r\n  // Copy Cloudflare API Token\r\n  else if(t.id === \"cpCfTokBtn\"){\r\n    const v = $(\"#setCfTok\")?.value || \"\";\r\n    if(v) copyText(v, \"Cloudflare API Token disalin!\");\r\n  }\r\n  // Test/Verify Cloudflare Token\r\n  else if(t.id === \"btnTestCf\" || t.closest(\"#btnTestCf\")){\r\n    const btn = $(\"#btnTestCf\");\r\n    const orig = btn.innerHTML;\r\n    btn.disabled = true;\r\n    btn.innerHTML = `${icons.spinner} <span>Memeriksa...</span>`;\r\n    try{\r\n      const tok = ($(\"#setCfTok\")?.value || \"\").trim();\r\n      const res = await api(\"/api/settings/verify-cf\", { method: \"POST\", body: { token: tok } });\r\n      if(res.valid){\r\n        state.settings.tokenVerified = true;\r\n        state.settings.tokenStatusMsg = res.message;\r\n        toast(\"✓ Token Cloudflare aktif & valid!\");\r\n      }else{\r\n        state.settings.tokenVerified = false;\r\n        state.settings.tokenStatusMsg = res.error;\r\n        toast(\"Peringatan: \" + (res.error || \"Token di-revoke!\"));\r\n      }\r\n      render();\r\n    }catch(err){\r\n      toast(\"Gagal verifikasi: \" + err.message);\r\n    }finally{\r\n      btn.disabled = false;\r\n      btn.innerHTML = orig;\r\n    }\r\n  }\r\n  // Save Settings: Branding\r\n  else if(t.id === \"btnSaveBranding\"){\r\n    saveSettingsTab(t, {\r\n      appName: $(\"#setAppName\").value.trim(),\r\n      logoUrl: $(\"#setLogoUrl\").value.trim(),\r\n      theme: state.settings.theme\r\n    });\r\n  }\r\n  // Save Settings: Relay\r\n  else if(t.id === \"btnSaveRelay\"){\r\n    saveSettingsTab(t, {\r\n      targetRestrict: $(\"#setGtr\").checked\r\n    });\r\n  }\r\n  // Save Settings: Cloudflare API & Secrets\r\n  else if(t.id === \"btnSaveCf\"){\r\n    saveSettingsTab(t, {\r\n      cfAccountId: $(\"#setCfAcc\").value.trim(),\r\n      cfApiToken: $(\"#setCfTok\").value.trim()\r\n    });\r\n  }\r\n  // Save Settings: Admin\r\n  else if(t.id === \"btnSaveAdmin\"){\r\n    const payload = { adminEmail: $(\"#setAdminEmail\").value.trim() };\r\n    const p = $(\"#setAdminPass\").value;\r\n    if(p){\r\n      if(p.length < 12) return toast(\"Password minimal 12 karakter\");\r\n      payload.newPassword = p;\r\n    }\r\n    saveSettingsTab(t, payload);\r\n  }\r\n});\r\n\r\n// Settings tabs scroll listener\r\ndocument.addEventListener(\"scroll\", e => {\r\n  if(e.target && e.target.id === \"settingsTabs\"){\r\n    updateTabArrows();\r\n  }\r\n}, true);\r\nwindow.addEventListener(\"resize\", updateTabArrows);\r\n\r\n// Helper Save Settings per Tab with Spinner\r\nasync function saveSettingsTab(btn, payload){\r\n  const origHtml = btn.innerHTML;\r\n  btn.disabled = true;\r\n  btn.innerHTML = `${icons.spinner} <span>Menyimpan...</span>`;\r\n  try{\r\n    const res = await api(\"/api/settings\", { method: \"POST\", body: payload });\r\n    state.settings = { ...state.settings, ...res };\r\n    applyBranding();\r\n    toast(\"Pengaturan disimpan!\");\r\n    render();\r\n  }catch(err){\r\n    btn.disabled = false;\r\n    btn.innerHTML = origHtml;\r\n    toast(\"Gagal simpan: \" + err.message);\r\n  }\r\n}\r\n\r\n// Dirty Check Handlers for Settings Inputs\r\ndocument.addEventListener(\"input\", e => {\r\n  const id = e.target.id;\r\n  if(id === \"setAppName\" || id === \"setLogoUrl\"){\r\n    const b = $(\"#btnSaveBranding\"); if(b) b.disabled = false;\r\n  } else if(id === \"setGtr\"){\r\n    const b = $(\"#btnSaveRelay\"); if(b) b.disabled = false;\r\n  } else if(id === \"setCfAcc\" || id === \"setCfTok\"){\r\n    const b = $(\"#btnSaveCf\"); if(b) b.disabled = false;\r\n  } else if(id === \"setAdminEmail\" || id === \"setAdminPass\"){\r\n    const b = $(\"#btnSaveAdmin\"); if(b) b.disabled = false;\r\n  }\r\n});\r\n\r\n// Auth Handlers\r\n$(\"#go\").innerHTML = `${icons.relay} <span>Log in</span>`;\r\n$(\"#go\").onclick = async () => {\r\n  const email = $(\"#em\").value.trim();\r\n  const password = $(\"#pw\").value;\r\n  if(!email || !password) return toast(\"Isi email dan password\");\r\n\r\n  const btn = $(\"#go\");\r\n  btn.disabled = true;\r\n  btn.innerHTML = `${icons.spinner} <span>Logging in...</span>`;\r\n\r\n  try{\r\n    await api(\"/api/auth/login\", { method: \"POST\", body: { email, password } });\r\n    window.location.href = \"/dashboard/clients\";\r\n  }catch(err){\r\n    toast(\"Login gagal: \" + err.message);\r\n  } finally {\r\n    btn.disabled = false;\r\n    btn.innerHTML = `${icons.relay} <span>Log in</span>`;\r\n  }\r\n};\r\n$(\"#pw\").addEventListener(\"keydown\", e => { if(e.key === \"Enter\") $(\"#go\").click(); });\r\n\r\nconst logout = async () => {\r\n  try{ await api(\"/api/auth/logout\", { method: \"POST\" }); }catch{}\r\n  window.location.href = \"/login\";\r\n};\r\n$(\"#out\").innerHTML = `${icons.logout} <span class=\"l\">Log out</span>`;\r\n$(\"#out\").onclick = logout;\r\n$(\"#mOut\").innerHTML = icons.logout;\r\n$(\"#mOut\").onclick = logout;\r\ndocument.addEventListener(\"click\", e => { if(e.target.closest(\"#out2\")) logout(); });\r\n\r\n// Set Navigation Labels with Icons\r\n$(\"#navClients\").innerHTML = `${icons.clients} <span>Clients</span>`;\r\n$(\"#navTargets\").innerHTML = `${icons.targets} <span>Targets</span>`;\r\n$(\"#navLogs\").innerHTML = `${icons.logs} <span>Logs</span>`;\r\n$(\"#navSettings\").innerHTML = `${icons.settings} <span>Settings</span>`;\r\n\r\n// If directly on /login, display login card immediately without wait\r\nif(window.location.pathname === \"/login\"){\r\n  $(\"#login\").classList.remove(\"hide\");\r\n}\r\n\r\n// Boot\r\nconst savedTheme = localStorage.getItem(\"relay_theme\") || \"auto\";\r\nif(savedTheme !== \"auto\") document.documentElement.dataset.theme = savedTheme;\r\n\r\n(async()=>{\r\n  try{\r\n    const st = await api(\"/api/auth/status\");\r\n    if(st.branding){\r\n      state.settings = { ...state.settings, ...st.branding };\r\n      applyBranding();\r\n      if(st.branding.theme && st.branding.theme !== \"auto\" && !localStorage.getItem(\"relay_theme\")){\r\n        document.documentElement.dataset.theme = st.branding.theme;\r\n      }\r\n    }\r\n    if(st.loggedIn){\r\n      showApp();\r\n      if(window.location.pathname === \"/login\" || window.location.pathname === \"/\"){\r\n        window.location.href = \"/dashboard/clients\";\r\n        return;\r\n      }\r\n      state.view = getViewFromPath();\r\n      render();\r\n      await syncAll();\r\n    }else{\r\n      if(window.location.pathname !== \"/login\"){\r\n        window.location.href = \"/login\";\r\n      }else{\r\n        showLogin(false);\r\n      }\r\n    }\r\n  }catch{\r\n    if(window.location.pathname !== \"/login\"){\r\n      window.location.href = \"/login\";\r\n    }else{\r\n      showLogin(false);\r\n    }\r\n  }\r\n})();\r\n</script>\r\n</body>\r\n</html>\r\n";
export default dashboardHtml;
